<?php
require_once dirname(__DIR__).'/app/bootstrap.php';require_role(['teacher','admin']);$learnerId=request_int('id');$learner=Database::fetch("SELECT id,name,username,email,age_group,school_name,points,last_login_at,created_at FROM users WHERE id=? AND role='learner'",[$learnerId]);if(!$learner){flash('error','The learner account could not be found.');redirect('teacher/dashboard.php');}
$courseProgress=Database::fetchAll("SELECT c.title,c.slug,c.colour,COUNT(l.id) AS lessons,COUNT(CASE WHEN p.status='completed' THEN 1 END) AS completed FROM courses c JOIN lessons l ON l.course_id=c.id LEFT JOIN progress p ON p.lesson_id=l.id AND p.user_id=? WHERE c.is_published=1 AND l.is_published=1 GROUP BY c.id ORDER BY c.sort_order",[$learnerId]);$attempts=Database::fetchAll('SELECT qa.score,qa.passed,qa.created_at,l.title,l.slug FROM quiz_attempts qa JOIN lessons l ON l.id=qa.lesson_id WHERE qa.user_id=? ORDER BY qa.created_at DESC LIMIT 15',[$learnerId]);$projects=Learning::projects($learnerId);$badges=array_filter(Learning::badges($learnerId),fn($b)=>(int)$b['earned']);
$pageTitle='Learner report';$bodyClass='learner-report-page';require base_path('partials/header.php');
?>
<a class="back-link" href="<?= e(url('teacher/dashboard.php')) ?>"><?= icon('arrow-left') ?>Teacher centre</a><section class="learner-profile-header"><span class="avatar xlarge"><?= e(initials($learner['name'])) ?></span><div><span class="eyebrow">Learner report</span><h1><?= e($learner['name']) ?></h1><p><?= e($learner['school_name']) ?> · <?= e($learner['age_group']) ?> years · joined <?= e(date('j M Y',strtotime($learner['created_at']))) ?></p></div><div class="points-pill"><?= icon('trophy') ?><span><strong><?= number_format((int)$learner['points']) ?></strong><small>points</small></span></div></section>
<div class="report-grid"><section class="panel"><div class="panel-heading"><div><span class="eyebrow">Curriculum</span><h2>Path progress</h2></div></div><div class="progress-course-list"><?php foreach($courseProgress as $course):$percent=(int)$course['lessons']?(int)round((int)$course['completed']/(int)$course['lessons']*100):0; ?><a href="<?= e(url('course.php?course='.urlencode($course['slug']))) ?>"><span class="course-icon compact" style="--course:<?= e($course['colour']) ?>"><?= icon('book-open') ?></span><span><strong><?= e($course['title']) ?></strong><small><?= (int)$course['completed'] ?> of <?= (int)$course['lessons'] ?> lessons</small><span class="progress-track"><i style="width:<?= $percent ?>%"></i></span></span><b><?= $percent ?>%</b></a><?php endforeach; ?></div></section><section class="panel"><div class="panel-heading"><div><span class="eyebrow">Assessments</span><h2>Recent quiz history</h2></div></div><div class="attempt-list"><?php foreach($attempts as $attempt): ?><a href="<?= e(url('quiz.php?lesson='.urlencode($attempt['slug']))) ?>"><span class="score-badge <?= (int)$attempt['passed']?'success':'warning' ?>"><?= (int)$attempt['score'] ?>%</span><span><strong><?= e($attempt['title']) ?></strong><small><?= e(time_ago($attempt['created_at'])) ?></small></span><?= icon('arrow-right') ?></a><?php endforeach; ?><?php if(!$attempts): ?><div class="compact-empty">No quiz attempts have been submitted.</div><?php endif; ?></div></section><section class="panel"><div class="panel-heading"><div><span class="eyebrow">Created work</span><h2>Saved projects</h2></div><span class="count-badge"><?= count($projects) ?></span></div><div class="mini-project-list"><?php foreach($projects as $project): ?><article><span><?= icon('terminal') ?></span><div><strong><?= e($project['title']) ?></strong><small>Updated <?= e(time_ago($project['updated_at'])) ?></small></div></article><?php endforeach; ?><?php if(!$projects): ?><div class="compact-empty">No projects have been saved.</div><?php endif; ?></div></section><section class="panel"><div class="panel-heading"><div><span class="eyebrow">Achievements</span><h2>Earned badges</h2></div><span class="count-badge"><?= count($badges) ?></span></div><div class="badge-stack"><?php foreach($badges as $badge): ?><div><span><?= icon($badge['icon']) ?></span><div><strong><?= e($badge['name']) ?></strong><small><?= e($badge['description']) ?></small></div></div><?php endforeach; ?><?php if(!$badges): ?><div class="compact-empty">No badges have been earned.</div><?php endif; ?></div></section></div>
<?php require base_path('partials/footer.php'); ?>
